ALTER TABLE "tournament_matches" DROP CONSTRAINT "tournament_matches_result_type_consistency";--> statement-breakpoint
ALTER TABLE "tournament_participants" DROP CONSTRAINT "tournament_participants_withdrawal_check";--> statement-breakpoint
ALTER TABLE "tournament_matches" ADD CONSTRAINT "tournament_matches_result_type_consistency" CHECK (("tournament_matches"."status" = 'COMPLETED' and "tournament_matches"."result_type" is not null and "tournament_matches"."result_type" in ('PLAYED', 'WALKOVER')) or ("tournament_matches"."status" = 'BYE' and "tournament_matches"."result_type" is not null and "tournament_matches"."result_type" = 'BYE') or ("tournament_matches"."status" not in ('COMPLETED', 'BYE') and "tournament_matches"."result_type" is null));--> statement-breakpoint
ALTER TABLE "tournament_participants" ADD CONSTRAINT "tournament_participants_withdrawal_check" CHECK (("tournament_participants"."status" = 'ACTIVE' and "tournament_participants"."withdrawn_at" is null and "tournament_participants"."withdrawal_reason" is null) or ("tournament_participants"."status" = 'WITHDRAWN' and "tournament_participants"."withdrawn_at" is not null and "tournament_participants"."withdrawal_reason" is not null and length(trim("tournament_participants"."withdrawal_reason")) between 3 and 500));